package org.rabochaya.projects;
import java.io.*;import java.util.*;
/** Read-only BITMAPINFOHEADER/BI_RGB 24/32bpp. 32bpp high byte is reserved, NOT alpha. */
public final class BmpRaster implements Closeable {
 public static final long MAX_FILE=512L*1024*1024;public final int width,height;private final RandomAccessFile file;private final boolean topDown;private final int samples,stride;private final long offset;private boolean closed;private long bytes;private final LinkedHashMap<Long,Tile> tiles=new LinkedHashMap<>(16,.75f,true);
 private static final class Tile {final int width;final int[] pixels;Tile(int width,int height){this.width=width;pixels=new int[width*height];}}
 private static long u32(byte[] a,int at){return (a[at]&255L)|(a[at+1]&255L)<<8|(a[at+2]&255L)<<16|(a[at+3]&255L)<<24;}
 private static int u16(byte[] a,int at){return (a[at]&255)|(a[at+1]&255)<<8;}
 public BmpRaster(File source)throws IOException{
  RandomAccessFile opened=new RandomAccessFile(source,"r");try{long length=opened.length();if(length<54||length>MAX_FILE)throw new IOException("BMP: предел 54 байта — 512 МиБ");byte[] header=new byte[54];opened.readFully(header);if(header[0]!=66||header[1]!=77||u32(header,2)!=length||u16(header,6)!=0||u16(header,8)!=0)throw new IOException("BMP: неверный file header/размер");if(u32(header,14)!=40||u16(header,26)!=1||u32(header,30)!=0||u32(header,46)!=0)throw new IOException("BMP: поддержан только INFOHEADER40 / BI_RGB без палитры");int w=(int)u32(header,18),signedHeight=(int)u32(header,22),bits=u16(header,28);long h=Math.abs((long)signedHeight);if(w<1||h<1||w>20000||h>20000||(long)w*h>100000000||(bits!=24&&bits!=32))throw new IOException("BMP: нужны 24/32bit, до 20 000 по стороне / 100 млн пикселей");long row=((w*(long)bits+31)/32)*4,span=row*h,start=u32(header,10),declared=u32(header,34);if(start<54||start>length||span>length-start||start+span!=length||declared!=0&&declared!=span)throw new IOException("BMP: неверные offset/stride/размер пикселей или лишние данные");width=w;height=(int)h;topDown=signedHeight<0;samples=bits/8;stride=(int)row;offset=start;file=opened;}catch(IOException|RuntimeException e){opened.close();if(e instanceof IOException)throw (IOException)e;throw new IOException("BMP: повреждённый заголовок",e);}
 }
 /** Bounded raw region LRU, independent of affine sampling order. */
 public synchronized int pixel(int x,int y)throws IOException{if(closed)throw new IOException("BMP reader закрыт");if(x<0||y<0||x>=width||y>=height)return 0;int tx=x/256,ty=y/256;long key=(long)ty<<32|tx;Tile tile=tiles.get(key);if(tile==null){int left=tx*256,top=ty*256,w=Math.min(256,width-left),h=Math.min(256,height-top);tile=new Tile(w,h);byte[] row=new byte[w*samples];for(int j=0;j<h;j++){int sourceRow=topDown?top+j:height-1-top-j;file.seek(offset+(long)sourceRow*stride+(long)left*samples);file.readFully(row);for(int i=0;i<w;i++){int at=i*samples;tile.pixels[j*w+i]=0xff000000|(row[at+2]&255)<<16|(row[at+1]&255)<<8|(row[at]&255);}}long size=tile.pixels.length*4L;while(!tiles.isEmpty()&&(tiles.size()>=64||bytes+size>16L*1024*1024)){Iterator<Map.Entry<Long,Tile>> iterator=tiles.entrySet().iterator();Tile old=iterator.next().getValue();iterator.remove();bytes-=old.pixels.length*4L;}tiles.put(key,tile);bytes+=size;}return tile.pixels[(y%256)*tile.width+x%256];}
 public synchronized void close()throws IOException{if(closed)return;closed=true;tiles.clear();bytes=0;file.close();}
}
